def calc(expr: str) -> int:
    pos = [0]

    def peek():
        while pos[0] < len(expr) and expr[pos[0]].isspace():
            pos[0] += 1
        if pos[0] < len(expr):
            return expr[pos[0]]
        return None

    def consume(char=None):
        while pos[0] < len(expr) and expr[pos[0]].isspace():
            pos[0] += 1
        if char is None:
            if pos[0] < len(expr):
                c = expr[pos[0]]
                pos[0] += 1
                return c
            return None
        if pos[0] < len(expr) and expr[pos[0]] == char:
            pos[0] += 1
            return char
        return None

    def parse_number():
        start = pos[0]
        while pos[0] < len(expr) and expr[pos[0]].isdigit():
            pos[0] += 1
        return int(expr[start:pos[0]])

    def parse_primary():
        # Handle unary minus and parentheses
        c = peek()
        if c == '-':
            consume('-')
            return -parse_primary()
        elif c == '+':
            consume('+')
            return parse_primary()
        elif c == '(':
            consume('(')
            result = parse_additive()
            consume(')')
            return result
        else:
            return parse_number()

    def parse_multiplicative():
        left = parse_primary()
        while peek() in ['*', '/']:
            op = consume()
            right = parse_primary()
            if op == '*':
                left = left * right
            else:  # op == '/'
                # Truncate toward zero
                left = int(left / right)
        return left

    def parse_additive():
        left = parse_multiplicative()
        while peek() in ['+', '-']:
            op = consume()
            right = parse_multiplicative()
            if op == '+':
                left = left + right
            else:  # op == '-'
                left = left - right
        return left

    result = parse_additive()
    return result

